/bin/zsh -lc "cat > package.json <<'EOF'
{\"name\":\"gpt-6-mail\",\"version\":\"1.0.0\",\"private\":true,\"type\":\"module\",\"scripts\":{\"dev\":\"node server.mjs --port 9196\",\"start\":\"node server.mjs --port 9196\",\"build\":\"node --check src/main.js && node --check server.mjs\",\"test\":\"node --test src/mail.test.js\"}}
EOF
cat > server.mjs <<'EOF'
import http from 'node:http';
import {readFile} from 'node:fs/promises';
import path from 'node:path';
const root=process.cwd();
http.createServer(async(req,res)=>{try{const url=new URL(req.url,'http://localhost');const file=path.resolve(root,'.'+decodeURIComponent(url.pathname==='/'?'/index.html':url.pathname));if("'!file.startsWith(root+path.sep))throw Error();const data=await readFile(file);res.setHeader('"'Content-Type',({'html':'text/html','js':'text/javascript','css':'text/css','svg':'image/svg+xml'})[file.split('.').pop()]||'application/octet-stream');res.end(data)}catch{res.writeHead(404);res.end('Not found')}}).listen(9196,'0.0.0.0',()=>console.log('GPT-6 mail listening on http://localhost:9196'));
EOF
cat > index.html <<'EOF'
<"'!doctype html><html lang="en"><head><meta charset="UTF-8"/><meta name="viewport" content="width=device-width, initial-scale=1.0"/><meta name="theme-color" content="#f7f8fa"/><title>GPT-6</title><link rel="stylesheet" href="/src/style.css"/></head><body><div id="root"></div><script type="module" src="/src/main.js"></script></body></html>
EOF
cat > src/mail.js <<'"'EOF'
