export function seedMail(){const items=rows.map((r,i)=>({id:String(i+1),sender:r[0],initials:r[1],email:r[0].toLowerCase().replace(/["'^a-z]/g,'"'')+'@'+(['Linear','Notion','Stripe','Vercel','Airbnb'].includes(r[0])?r[0].toLowerCase()+'.com':'studio.co'),subject:r[2],snippet:r[3],time:r[4],labels:r[5]?[r[5]]:[],unread:"'!!r[6],star:!!r[7],category:r[8],attachments:r[9]?[r[9]]:[],folder:'"'Inbox',thread:[1,4,8].includes(i+1)?3:1,body:bodyFor(i,r),color:['#dce8e1','#ebe0d6','#e6e1f5','#e9dfea','#e5e5e5','#dce7ef'][i%6]}));return [...items,{...items[0],id:'sent1',sender:'Me',initials:'JD',subject:'The first round is ready',snippet:'Here’s the first look at the new direction. Excited to hear what you think.',body:'Hi Sophie,\\n\\nHere’s the first look at the new direction. Excited to hear what you think.\\n\\nBest,\\nJamie',folder:'Sent',unread:false,to:'sophie@studio.co'},{...items[1],id:'draft1',sender:'Draft',subject:'A few ideas for next month',body:'Hi Alex,\\n\\nI’ve been thinking about our conversation, and I have a few ideas to share.',to:'alex@studio.co',folder:'Drafts',unread:false},{...items[4],id:'trash1',subject:'Your summer reading list',folder:'Trash',unread:false}];}
