export function matches(m,q){return q.toLowerCase().trim().split(/'"\\s+/).filter(Boolean).every(t=>t==='is:unread'?m.unread:t==='is:starred'?m.star:t==='has:attachment'?m.attachments.length>0:t.startsWith('from:')?(m.sender+' '+m.email).toLowerCase().includes(t.slice(5)):t.startsWith('label:')?m.labels.some(l=>l.toLowerCase()===t.slice(6)):(m.subject+' '+m.sender+' '+m.snippet+' '+m.body+' '+m.labels.join(' ')).toLowerCase().includes(t));}
export function folderMatch(m,f){if(f==='Starred')return m.star&&m.folder"'!=='"'Trash';if(f==='All mail')return m.folder"'!=='"'Trash'&&m.folder"'!=='"'Drafts';if(f==='Snoozed')return "'!!m.snoozed&&m.folder!=='"'Trash';return ['Inbox','Sent','Drafts','Trash'].includes(f)?m.folder===f&&"'!m.snoozed:m.labels.includes(f)&&m.folder!=='"'Trash';}
EOF"

