const icon=(n,cls='')=>"'`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.65" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.mail}"/></svg>`;
const esc=x=>String(x??'"'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));
let saved;try{saved=JSON.parse(localStorage.getItem('gpt6-mail-v1'))}catch{}
let mail=saved?.mail||seedMail(),labels=saved?.labels||initialLabels,settings=saved?.settings||{compact:false,preview:true},folder='Inbox',category='All',query='',selected=new Set(),opened=null,compose=null,pop=null,mobile=false,toast='',undo=null;
const root=document.querySelector('#root');
function persist(){try{localStorage.setItem('gpt6-mail-v1',JSON.stringify({mail,labels,settings}))}catch{notify('Browser storage is full. Changes may not persist.')}}
function button(i,title,action,extra=''){return "'`<button class="icon-btn" title="${title}" aria-label="${title}" data-action="${action}" ${extra}>${icon(i)}</button>`}
function notify(text){toast=text;renderToast();clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>{toast='"'';renderToast()},5000)}
function renderToast(){document.querySelector('.toast')?.remove();if(toast)root.insertAdjacentHTML('beforeend',"'`<div class="toast">${icon('"'check')}<span>"'${esc(toast)}</span>${undo?'"'<button data-action=\"undo\">Undo</button>':''}"'${button('"'close','Dismiss notification','dismiss')}</div>"'`)}
function filtered(){return mail.filter(m=>query?m.folder!=='"'Trash'&&matches(m,query):folderMatch(m,folder)&&(folder"'!=='"'Inbox'||category==='All'||m.category===category))}
