function nav(name,i){const count=mail.filter(m=>folderMatch(m,name)&&(name==='Drafts'||m.unread)).length;return "'`<button class="nav-item ${folder===name&&!query?'"'active':''}\" data-nav=\""'${name}">${icon(i)}<span>${name}</span>${count?`<span class="nav-count">${count}</span>`:'"''}</button>"'`}
function render(){const list=filtered(),m=mail.find(m=>m.id===opened);root.innerHTML=`<div class="app ${settings.compact?'"'compact':''}\"><header class=\"header\"><div class=\"brand\">"'${button('"'menu','Toggle navigation','menu')}<div class=\"brand-symbol\">"'${icon('"'mail')}</div><h1>GPT-6</h1></div><div class=\"search-box\">"'${icon('"'search')}<input id=\"search\" aria-label=\"Search mail\" placeholder=\"Search mail\" value=\""'${esc(query)}" autocomplete="off"/>${query?button('"'close','Clear search','clear-search'):button('sliders','Search options','search-options')}</div><div class=\"header-right\"><span class=\"status\"><i></i> All synced</span>"'${button('"'help','Help and keyboard shortcuts','help')}"'${button('"'settings','Settings','settings')}<span class=\"header-divider\"></span><button class=\"account\" title=\"Your account\" data-action=\"account\">JD<span></span></button></div></header><div class=\"workspace\"><aside class=\"sidebar "'${mobile?'"'mobile-open':''}\"><button class=\"compose-btn\" data-action=\"compose\">"'${icon('"'edit')}<span>Compose</span>"'${icon('"'plus')}</button><div class=\"nav-list\">"'${nav('"'Inbox','inbox')}"'${nav('"'Starred','star')}"'${nav('"'Snoozed','clock')}"'${nav('"'Sent','send')}"'${nav('"'Drafts','draft')}"'${nav('"'Trash','trash')}"'${nav('"'All mail','archive')}</div><div class=\"labels-title\"><span>Labels</span>"'${button('"'plus','Create label','create-label')}</div><div class=\"label-list\">"'${labels.map(l=>`<button class="nav-item ${folder===l.name?'"'active':''}\" data-nav=\""'${esc(l.name)}"><span class="label-dot" style="background:${l.color}"></span><span>${esc(l.name)}</span><span class="label-count">${mail.filter(m=>m.labels.includes(l.name)&&m.folder!=='"'Trash').length}</span></button>"'`).join('"'')}</div><div class=\"sidebar-bottom\"><div class=\"storage-heading\">"'${icon('"'shield')}<span>Your space, in sync</span></div><div class=\"storage-bar\"><span></span></div><small>2.4 GB of 15 GB used</small><button data-action=\"storage\">Manage storage "'${icon('"'external')}</button><div class=\"local-note\"><span></span> A little more room to think.</div></div></aside><main class=\"mail-panel\">"'${m?reader(m):`<div class="inbox-title"><div><h2>${query?'"'Search results':esc(folder)}</h2><span>"'${query?`${list.length} conversation${list.length!==1?'"'s':''} found"'`:(folder==='"'Inbox'?'A fresh start. A little less noise.':"'`${list.length} conversations`)}</span></div><div class="title-actions"><span class="date">Wednesday, September 30</span>${button('"'more','Mailbox options','mailbox-menu')}</div></div><div class=\"toolbar\"><div class=\"toolbar-start\"><input type=\"checkbox\" aria-label=\"Select all messages\" id=\"select-all\" "'${list.length&&list.every(m=>selected.has(m.id))?'"'checked':''}/>"'${button('"'down','Selection options','selection-menu')}<span class=\"toolbar-separator\"></span>"'${selected.size?`${button('"'archive','Archive selected','archive')}"'${button('"'trash','Delete selected','trash')}"'${button('"'mail','Mark unread','unread')}"'${button('"'label','Label selected','labels')}<span class=\"selection-count\">"'${selected.size} selected</span>`:`${button('"'refresh','Refresh inbox','refresh')}"'${button('"'more','More actions','bulk-menu')}"'`}</div><div class="toolbar-end"><span>${list.length?`1–${list.length} of ${list.length}`:'"'0 conversations'}</span>"'${button('"'left','Previous page','previous-page')}"'${button('"'right','Next page','next-page')}<span class=\"toolbar-separator\"></span>"'${button('"'sliders','Display settings','settings')}</div></div>"'${folder==='"'Inbox'&&"'!query?`<div class="tabs">${[['"'All','inbox','Primary'],['Promotions','label','Promotions'],['Updates','clock','Updates']].map(([c,i,t])=>"'`<button data-category="${c}" class="tab ${category===c?'"'active':''}\">"'${icon(i)}<span>${t}</span>${c==='"'All'?"'`<span class="tab-count">${mail.filter(m=>m.folder==='"'Inbox'&&m.unread).length} new</span>"'`:c==='"'Promotions'?'<span class=\"tiny-dot\"></span>':''}</button>"'`).join('"'')}</div>"'`:'"''}<div class=\"message-list\">"'${list.length?list.map(row).join('"''):"'`<div class="empty">${icon(query?'"'search':'inbox')}<h3>"'${query?'"'No conversations found':'A little breathing room.'}</h3><p>"'${query?'"'Try another name, subject, or search term.':"'`There’s nothing in ${esc(folder.toLowerCase())} right now.`}</p>${query?'"'<button class=\"text-btn\" data-action=\"clear-search\">Clear search</button>':''}</div>"'`}</div><footer class="mail-footer"><span>Everything in its right place.</span><span>${icon('"'shield')} Private. Secure. Yours.</span></footer>"'`}</main><aside class="utility-rail">${button('"'calendar','Calendar','calendar')}"'${button('"'bulb','Notes','notes')}"'${button('"'check','Tasks','tasks')}"'${button('"'users','Contacts','contacts')}<div></div>"'${button('"'plus','Add a quick note','notes')}<span class=\"rail-bottom\">"'${button('"'right','Hide side panel','hide-rail')}</span></aside></div>"'${compose?composeView():'"''}"'${pop?popup():'"''}</div>"'`;bind();renderToast()}
function row(m){return `<div class="mail-row ${m.unread?'"'unread':''} "'${selected.has(m.id)?'"'selected':''}\" data-open=\""'${m.id}" tabindex="0" role="button" aria-label="Open ${esc(m.subject)}"><div class="row-select"><input type="checkbox" aria-label="Select ${esc(m.subject)}" data-select="${m.id}" ${selected.has(m.id)?'"'checked':''}/><button class=\"star-button "'${m.star?'"'starred':''}\" aria-label=\""'${m.star?'"'Unstar':'Star'} "'${esc(m.subject)}" data-star="${m.id}">${icon('"'star')}</button></div><div class=\"avatar\" style=\"background:"'${m.color}">${esc(m.initials)}</div><div class="sender">${m.folder==='"'Drafts'?'<span class=\"draft-text\">Draft</span>':esc(m.sender)}"'${m.thread>1?` <small>${m.thread}</small>`:'"''}</div><div class=\"mail-content\"><span class=\"subject\">"'${esc(m.subject)}</span>${settings.preview?`<span class="snippet"> <span class="dash">—</span> ${esc(m.snippet)}</span>`:'"''}</div><div class=\"row-meta\">"'${m.labels.slice(0,1).map(labelChip).join('"'')}"'${m.attachments.length?icon('"'paperclip','attachment-indicator'):''}<time>"'${m.time}</time></div><div class="row-hover">${button('"'archive','Archive message','row-archive',"'`data-id="${m.id}"`)}${button('"'trash','Delete message','row-trash',"'`data-id="${m.id}"`)}</div></div>`}
function labelChip(l){return `<span class="label-chip" style="--label:${labels.find(x=>x.name===l)?.color||'"'#aaa'}\">"'${esc(l)}</span>`}
function reader(m){return `<div class="reader-toolbar">${button('"'back','Back to mailbox','back')}<span class=\"toolbar-separator\"></span>"'${button('"'archive','Archive conversation','archive')}"'${button('"'trash','Delete conversation','trash')}"'${button('"'mail','Mark unread','unread')}"'${button('"'clock',m.snoozed?'Unsnooze conversation':'Snooze conversation','snooze')}"'${button('"'label','Label conversation','labels')}<div class=\"reader-spacer\"></div>"'${button('"'left','Previous conversation','prev-message')}"'${button('"'right','Next conversation','next-message')}</div><div class=\"reading-scroll\"><div class=\"conversation-heading\"><h2>"'${esc(m.subject)}</h2><div>${m.labels.map(labelChip).join('"'')}</div></div>"'${m.thread>1?`<div class="collapsed-message"><div class="avatar me">JD</div><div><b>Jamie Davis</b><p>Sharing the latest with you. Would love to hear your thoughts!</p></div><time>Sep 29, 4:12 PM</time></div><div class="collapsed-message"><div class="avatar" style="background:${m.color}">${esc(m.initials)}</div><div><b>${esc(m.sender)}</b><p>Thanks for sending this over! I’ll take a closer look in the morning.</p></div><time>Sep 29, 4:38 PM</time></div>`:'"''}<article class=\"message-body\"><div class=\"message-head\"><div class=\"avatar\" style=\"background:"'${m.color}">${esc(m.initials)}</div><div><b>${esc(m.sender)}</b> <span class="email-address">&lt;${esc(m.email)}&gt;</span><p>to ${m.folder==='"'Sent'?esc(m.to):'me'} "'${icon('"'down')}</p></div><time>"'${m.time}</time><button class="star-button ${m.star?'"'starred':''}\" aria-label=\"Star conversation\" data-star=\""'${m.id}">${icon('"'star')}</button>"'${button('"'reply','Reply','reply')}</div><div class=\"body-copy\">"'${esc(m.body).replace(/'"\\n/g,'<br>')}</div>"'${m.attachments.length?`<div class="attachments"><p>${m.attachments.length} attachment <span>· Scanned and safe</span></p>${m.attachments.map(a=>`<button class="attachment-card" data-download="${esc(a)}"><span class="file-icon">${icon('"'draft')}</span><span><b>"'${esc(a)}</b><small>Document · 248 KB</small></span>${icon('"'download')}</button>"'`).join('"'')}</div>"'`:'"''}<div class=\"reply-actions\"><button class=\"outline-btn\" data-action=\"reply\">"'${icon('"'reply')} Reply</button><button class=\"outline-btn\" data-action=\"forward\">"'${icon('"'send')} Forward</button>"'${m.folder==='"'Trash'?'<button class=\"outline-btn\" data-action=\"restore\">Restore to inbox</button>':''}</div></article></div>"'`}
function composeView(){return `<section class="compose-window ${compose.max?'"'maximized':''} "'${compose.min?'"'minimized':''}\" aria-label=\"Compose email\"><div class=\"compose-header\"><b>"'${compose.reply?'"'Reply':'New message'}</b><span>"'${button('"'minus','Minimize compose','min-compose')}"'${button('"'external','Expand compose','max-compose')}"'${button('"'close','Save and close draft','close-compose')}</span></div><form id=\"compose-form\"><div class=\"compose-field\"><label for=\"to\">To</label><input id=\"to\" type=\"email\" multiple required placeholder=\"Recipients\" value=\""'${esc(compose.to)}" list="contacts"/><datalist id="contacts">${mail.slice(0,18).map(m=>`<option value="${esc(m.email)}">${esc(m.sender)}</option>`).join('"'')}</datalist><button type=\"button\" class=\"text-btn\" data-action=\"cc\">Cc</button></div>"'${compose.showCc?`<div class="compose-field"><label for="cc">Cc</label><input id="cc" type="email" multiple value="${esc(compose.cc||'"'')}\" placeholder=\"Copy recipients\"/></div>"'`:'"''}<div class=\"compose-field\"><input id=\"subject\" aria-label=\"Subject\" placeholder=\"Subject\" value=\""'${esc(compose.subject)}"/></div><textarea id="body" aria-label="Message body" placeholder="A little hello goes a long way…">${esc(compose.body)}</textarea>${compose.attachments.length?`<div class="compose-files">${compose.attachments.map(a=>`<span>${icon('"'paperclip')}"'${esc(a)}</span>`).join('"'')}</div>"'`:'"''}<div class=\"draft-status\">"'${icon('"'check')} Draft saved locally</div><div class=\"compose-bottom\"><button type=\"submit\" class=\"send-btn\">Send "'${icon('"'send')}</button>"'${button('"'paperclip','Attach files','attach')}<input id=\"file-input\" type=\"file\" multiple hidden/>"'${button('"'image','Attach image','attach-image')}<span class=\"compose-spacer\"></span>"'${button('"'trash','Discard draft','discard-compose')}</div></form></section>"'`}
function popup(){let title='"'',content='';switch(pop.type){case 'labels':title='Label conversations';content=labels.map(l=>"'`<button class="popup-row" data-apply-label="${esc(l.name)}"><span class="label-dot" style="background:${l.color}"></span>${esc(l.name)} ${mail.filter(m=>(selected.has(m.id)||m.id===opened)&&m.labels.includes(l.name)).length?icon('"'check'):''}</button>"'`).join('"'')+'<button class=\"popup-row\" data-action=\"create-label\">'+icon('plus')+' Create a label</button>';break;case 'create-label':title='A place for everything';content='<p>Create a label to keep related conversations together.</p><form id=\"label-form\"><input id=\"label-name\" placeholder=\"Label name\" required maxlength=\"25\" autofocus/><button class=\"send-btn\">Create label</button></form>';break;case 'settings':title='Make yourself at home';content="'`<p>A few small details, just the way you like them.</p><label class="setting-row"><span><b>Compact density</b><small>More conversations, less scrolling.</small></span><input type="checkbox" id="setting-compact" ${settings.compact?'"'checked':''}/></label><label class=\"setting-row\"><span><b>Message previews</b><small>A little context before you open.</small></span><input type=\"checkbox\" id=\"setting-preview\" "'${settings.preview?'"'checked':''}/></label><div class=\"setting-info\">"'${icon('"'shield')} Your preferences and mail are saved on this device.</div>"'`;break;case '"'account':title='Good morning, Jamie.';content='<div class=\"account-card\"><div class=\"account large\">JD</div><h3>Jamie Davis</h3><p>jamie@studio.co</p><span class=\"account-badge\">Personal workspace</span></div><div class=\"setting-info\">You’re using a private, local mailbox. No external account is connected.</div>';break;case 'help':title='A little help, a lot of flow';content='<p>Your inbox, at your fingertips.</p>'+[['C','Compose a message'],['/','Search your mail'],['Esc','Close a panel or conversation'],['E','Archive an open conversation'],['#','Move a conversation to Trash'],['?','Show keyboard shortcuts']].map(([k,v])=>"'`<div class="shortcut"><span>${v}</span><kbd>${k}</kbd></div>`).join('"'');break;case 'search-options':title='Find just what you need';content='<form id=\"filter-form\"><label>From<input name=\"from\" placeholder=\"Name or email address\"/></label><label>Contains the words<input name=\"words\" placeholder=\"Project, plans, coffee…\"/></label><label class=\"filter-check\"><input type=\"checkbox\" name=\"unread\"/> Unread only</label><label class=\"filter-check\"><input type=\"checkbox\" name=\"attachment\"/> Has an attachment</label><button class=\"send-btn\">Search mail</button></form>';break;case 'snooze':title='Come back to it later';content=[['Later today','Today, 6:00 PM'],['Tomorrow','Oct 1, 9:00 AM'],['Next week','Oct 5, 9:00 AM']].map(([a,b])=>"'`<button class="popup-row" data-snooze="${b}">${icon('"'clock')}<b>"'${a}</b><small>${b}</small></button>`).join('"'');break;case 'contacts':title='Good people, one click away';content='<div class=\"contacts-list\">'+mail.slice(0,12).map(m=>"'`<button class="contact" data-contact="${esc(m.email)}"><span class="avatar" style="background:${m.color}">${esc(m.initials)}</span><span><b>${esc(m.sender)}</b><small>${esc(m.email)}</small></span>${icon('"'edit')}</button>"'`).join('"'')+'</div>';break;case 'notes':title='A little space for your thoughts';content="'`<textarea id="quick-note" class="notes" placeholder="An idea, a reminder, something worth keeping…">${esc(localStorage.getItem('"'gpt6-note')||'Remember to send Sophie the updated brand references.\\n\\nCoffee with Alex next week ☕')}</textarea><small>Saved automatically on this device.</small>"'`;break;case '"'tasks':title='One thing at a time';content='<form id=\"task-form\"><input id=\"task-name\" required placeholder=\"Add a task…\"/><button class=\"send-btn\">Add</button></form><div id=\"task-list\">'+readTasks().map((t,i)=>"'`<label class="task ${t.done?'"'done':''}\"><input type=\"checkbox\" data-task=\""'${i}" ${t.done?'"'checked':''}/>"'${esc(t.text)}</label>`).join('"'')+'</div>';break;case 'calendar':title='Today, at a glance';content='<p>Wednesday, September 30</p><div class=\"calendar-grid\">'+['M','T','W','T','F','S','S',...Array.from({length:30},(_,i)=>i+1)].map(n=>"'`<span class="${n===30?'"'today':''}\">"'${n}</span>`).join('"'')+'</div><div class=\"event\"><small>11:00 – 11:30 AM</small><b>Brand direction catch-up</b><span>With Sophie Chen · Studio</span></div><div class=\"event purple\"><small>2:00 – 3:00 PM</small><b>A little focus time</b><span>Make room for the good work.</span></div>';break;case 'storage':title='Room for what matters';content='<p>This demonstration mailbox is stored entirely in your browser. Attachments are local previews, and sending adds messages to Sent without delivering external email.</p><div class=\"setting-info\">'+icon('shield')+' Your data stays on this device.</div>';break;default:title='Mailbox actions';content='<button class=\"popup-row\" data-action=\"mark-all-read\">'+icon('mail')+' Mark all as read</button><button class=\"popup-row\" data-action=\"select-unread\">'+icon('check')+' Select unread messages</button><button class=\"popup-row\" data-action=\"select-starred\">'+icon('star')+' Select starred messages</button>';}return "'`<div class="modal-overlay" data-action="overlay-close"><section class="popup" role="dialog" aria-modal="true" aria-label="${title}"><div class="popup-heading"><h3>${title}</h3>${button('"'close','Close dialog','close-pop')}</div>"'${content}</section></div>`}
function readTasks(){try{return JSON.parse(localStorage.getItem('"'gpt6-tasks'))||[{text:'Review the new brand direction',done:false},{text:'Send September invoice',done:true}]}catch{return []}}
function startCompose(data={}){compose={id:crypto.randomUUID(),to:'',subject:'',body:'',attachments:[],...data};pop=null;render();document.querySelector('#to')?.focus()}
function saveDraft(){if("'!compose)return;let d={...compose,sender:'"'Draft',initials:'JD',email:'jamie@studio.co',snippet:compose.body.replace(/\\n/g,' '),time:'Draft',folder:'Drafts',unread:false,star:false,labels:[],category:'Primary',thread:1,color:'#e0e7da'};const index=mail.findIndex(m=>m.id===compose.id);if(index>=0)mail[index]=d;else if(d.to||d.subject||d.body||d.attachments.length)mail.unshift(d);persist()}
function action(a,target){const ids=opened?[opened]:[...selected];if(['archive','trash','unread','restore'].includes(a)){if("'!ids.length){notify('"'Select a conversation first');return}const patch=a==='archive'?{folder:'Archive'}:a==='trash'?{folder:'Trash',snoozed:null}:a==='restore'?{folder:'Inbox',snoozed:null}:{unread:true};opened=null;mutate(ids,patch,a==='archive'?'Conversation archived':a==='trash'?'Moved to Trash':a==='restore'?'Restored to Inbox':'Marked as unread');return}switch(a){case 'menu':mobile="'!mobile;document.querySelector('"'.sidebar').classList.toggle('mobile-open',mobile);break;case 'compose':startCompose();break;case 'close-compose':saveDraft();compose=null;render();notify('Draft saved');break;case 'discard-compose':mail=mail.filter(m=>m.id"'!==compose.id);compose=null;persist();render();notify('"'Draft discarded');break;case 'min-compose':compose.min="'!compose.min;render();break;case '"'max-compose':compose.max="'!compose.max;compose.min=false;render();break;case '"'cc':compose.showCc="'!compose.showCc;render();break;case '"'attach':case 'attach-image':document.querySelector('#file-input').accept=a==='attach-image'?'image/*':'';document.querySelector('#file-input').click();break;case 'clear-search':query='';opened=null;render();document.querySelector('#search').focus();break;case 'back':opened=null;render();break;case 'row-archive':mutate([target.dataset.id],{folder:'Archive'},'Conversation archived');break;case 'row-trash':mutate([target.dataset.id],{folder:'Trash'},'Moved to Trash');break;case 'undo':if(undo){mail=JSON.parse(undo);undo=null;persist();render();notify('Action undone')}break;case 'dismiss':toast='';renderToast();break;case 'close-pop':pop=null;render();break;case 'overlay-close':if(target.classList.contains('modal-overlay')){pop=null;render()}break;case 'refresh':notify('All caught up. Your mailbox is synced.');break;case 'previous-page':case 'next-page':notify('You’re viewing all conversations in this mailbox.');break;case 'prev-message':case 'next-message':{const list=filtered(),idx=list.findIndex(m=>m.id===opened),next=list[idx+(a==='prev-message'?-1:1)];if(next)openMessage(next.id);else notify('No more conversations in this direction.');break}case 'reply':case 'forward':{const m=mail.find(m=>m.id===opened);startCompose({to:a==='reply'?m.email:'',subject:(a==='reply'?'Re: ':'Fwd: ')+m.subject,body:a==='forward'?"'`'"\\n\\n—— Forwarded message ——\\nFrom: "'${m.sender} <${m.email}>'"\\nSubject: "'${m.subject}'"\\n\\n"'${m.body}`:'"'',reply:a==='reply'});break}case 'mark-all-read':pop=null;mutate(filtered().map(m=>m.id),{unread:false},'All conversations marked as read');break;case 'select-unread':case 'select-starred':selected=new Set(filtered().filter(m=>a==='select-unread'?m.unread:m.star).map(m=>m.id));pop=null;render();break;case 'hide-rail':document.querySelector('.utility-rail').style.display='none';break;case 'snooze':if(mail.find(m=>m.id===opened)?.snoozed){mutate(ids,{snoozed:null},'Conversation unsnoozed');break}pop={type:a};render();break;default:if(a==='labels'&&"'!ids.length){notify('"'Select a conversation to label');return}pop={type:a};render();}}
