#','Move a conversation to Trash'],['?','Show keyboard shortcuts']].map(([k,v])=>"'`<div class="shortcut"><span>${v}</span><kbd>${k}</kbd></div>`).join('"'');break;case 'search-options':title='Find just what you need';content='<form id=\"filter-form\"><label>From<input name=\"from\" placeholder=\"Name or email address\"/></label><label>Contains the words<input name=\"words\" placeholder=\"Project, plans, coffee…\"/></label><label class=\"filter-check\"><input type=\"checkbox\" name=\"unread\"/> Unread only</label><label class=\"filter-check\"><input type=\"checkbox\" name=\"attachment\"/> Has an attachment</label><button class=\"send-btn\">Search mail</button></form>';break;case 'snooze':title='Come back to it later';content=[['Later today','Today, 6:00 PM'],['Tomorrow','Oct 1, 9:00 AM'],['Next week','Oct 5, 9:00 AM']].map(([a,b])=>"'`<button class="popup-row" data-snooze="${b}">${icon('"'clock')}<b>"'${a}</b><small>${b}</small></button>`).join('"'');break;case 'contacts':title='Good people, one click away';content='<div class=\"contacts-list\">'+mail.slice(0,12).map(m=>"'`<button class="contact" data-contact="${esc(m.email)}"><span class="avatar" style="background:${m.color}">${esc(m.initials)}</span><span><b>${esc(m.sender)}</b><small>${esc(m.email)}</small></span>${icon('"'edit')}</button>"'`).join('"'')+'</div>';break;case 'notes':title='A little space for your thoughts';content="'`<textarea id="quick-note" class="notes" placeholder="An idea, a reminder, something worth keeping…">${esc(localStorage.getItem('"'gpt6-note')||'Remember to send Sophie the updated brand references.\\n\\nCoffee with Alex next week ☕')}</textarea><small>Saved automatically on this device.</small>"'`;break;case '"'tasks':title='One thing at a time';content='<form id=\"task-form\"><input id=\"task-name\" required placeholder=\"Add a task…\"/><button class=\"send-btn\">Add</button></form><div id=\"task-list\">'+readTasks().map((t,i)=>"'`<label class="task ${t.done?'"'done':''}\"><input type=\"checkbox\" data-task=\""'${i}" ${t.done?'"'checked':''}/>"'${esc(t.text)}</label>`).join('"'')+'</div>';break;case 'calendar':title='Today, at a glance';content='<p>Wednesday, September 30</p><div class=\"calendar-grid\">'+['M','T','W','T','F','S','S',...Array.from({length:30},(_,i)=>i+1)].map(n=>"'`<span class="${n===30?'"'today':''}\">"'${n}</span>`).join('"'')+'</div><div class=\"event\"><small>11:00 – 11:30 AM</small><b>Brand direction catch-up</b><span>With Sophie Chen · Studio</span></div><div class=\"event purple\"><small>2:00 – 3:00 PM</small><b>A little focus time</b><span>Make room for the good work.</span></div>';break;case 'storage':title='Room for what matters';content='<p>This demonstration mailbox is stored entirely in your browser. Attachments are local previews, and sending adds messages to Sent without delivering external email.</p><div class=\"setting-info\">'+icon('shield')+' Your data stays on this device.</div>';break;default:title='Mailbox actions';content='<button class=\"popup-row\" data-action=\"mark-all-read\">'+icon('mail')+' Mark all as read</button><button class=\"popup-row\" data-action=\"select-unread\">'+icon('check')+' Select unread messages</button><button class=\"popup-row\" data-action=\"select-starred\">'+icon('star')+' Select starred messages</button>';}return "'`<div class="modal-overlay" data-action="overlay-close"><section class="popup" role="dialog" aria-modal="true" aria-label="${title}"><div class="popup-heading"><h3>${title}</h3>${button('"'close','Close dialog','close-pop')}</div>"'${content}</section></div>`}
function readTasks(){try{return JSON.parse(localStorage.getItem('"'gpt6-tasks'))||[{text:'Review the new brand direction',done:false},{text:'Send September invoice',done:true}]}catch{return []}}
function startCompose(data={}){compose={id:crypto.randomUUID(),to:'',subject:'',body:'',attachments:[],...data};pop=null;render();document.querySelector('#to')?.focus()}
function saveDraft(){if("'!compose)return;let d={...compose,sender:'"'Draft',initials:'JD',email:'jamie@studio.co',snippet:compose.body.replace(/\\n/g,' '),time:'Draft',folder:'Drafts',unread:false,star:false,labels:[],category:'Primary',thread:1,color:'#e0e7da'};const index=mail.findIndex(m=>m.id===compose.id);if(index>=0)mail[index]=d;else if(d.to||d.subject||d.body||d.attachments.length)mail.unshift(d);persist()}
function action(a,target){const ids=opened?[opened]:[...selected];if(['archive','trash','unread','restore'].includes(a)){if("'!ids.length){notify('"'Select a conversation first');return}const patch=a==='archive'?{folder:'Archive'}:a==='trash'?{folder:'Trash',snoozed:null}:a==='restore'?{folder:'Inbox',snoozed:null}:{unread:true};opened=null;mutate(ids,patch,a==='archive'?'Conversation archived':a==='trash'?'Moved to Trash':a==='restore'?'Restored to Inbox':'Marked as unread');return}switch(a){case 'menu':mobile="'!mobile;document.querySelector('"'.sidebar').classList.toggle('mobile-open',mobile);break;case 'compose':startCompose();break;case 'close-compose':saveDraft();compose=null;render();notify('Draft saved');break;case 'discard-compose':mail=mail.filter(m=>m.id"'!==compose.id);compose=null;persist();render();notify('"'Draft discarded');break;case 'min-compose':compose.min="'!compose.min;render();break;case '"'max-compose':compose.max="'!compose.max;compose.min=false;render();break;case '"'cc':compose.showCc="'!compose.showCc;render();break;case '"'attach':case 'attach-image':document.querySelector('#file-input').accept=a==='attach-image'?'image/*':'';document.querySelector('#file-input').click();break;case 'clear-search':query='';opened=null;render();document.querySelector('#search').focus();break;case 'back':opened=null;render();break;case 'row-archive':mutate([target.dataset.id],{folder:'Archive'},'Conversation archived');break;case 'row-trash':mutate([target.dataset.id],{folder:'Trash'},'Moved to Trash');break;case 'undo':if(undo){mail=JSON.parse(undo);undo=null;persist();render();notify('Action undone')}break;case 'dismiss':toast='';renderToast();break;case 'close-pop':pop=null;render();break;case 'overlay-close':if(target.classList.contains('modal-overlay')){pop=null;render()}break;case 'refresh':notify('All caught up. Your mailbox is synced.');break;case 'previous-page':case 'next-page':notify('You’re viewing all conversations in this mailbox.');break;case 'prev-message':case 'next-message':{const list=filtered(),idx=list.findIndex(m=>m.id===opened),next=list[idx+(a==='prev-message'?-1:1)];if(next)openMessage(next.id);else notify('No more conversations in this direction.');break}case 'reply':case 'forward':{const m=mail.find(m=>m.id===opened);startCompose({to:a==='reply'?m.email:'',subject:(a==='reply'?'Re: ':'Fwd: ')+m.subject,body:a==='forward'?"'`'"\\n\\n—— Forwarded message ——\\nFrom: "'${m.sender} <${m.email}>'"\\nSubject: "'${m.subject}'"\\n\\n"'${m.body}`:'"'',reply:a==='reply'});break}case 'mark-all-read':pop=null;mutate(filtered().map(m=>m.id),{unread:false},'All conversations marked as read');break;case 'select-unread':case 'select-starred':selected=new Set(filtered().filter(m=>a==='select-unread'?m.unread:m.star).map(m=>m.id));pop=null;render();break;case 'hide-rail':document.querySelector('.utility-rail').style.display='none';break;case 'snooze':if(mail.find(m=>m.id===opened)?.snoozed){mutate(ids,{snoozed:null},'Conversation unsnoozed');break}pop={type:a};render();break;default:if(a==='labels'&&"'!ids.length){notify('"'Select a conversation to label');return}pop={type:a};render();}}
function openMessage(id){const m=mail.find(m=>m.id===id);if(m.folder==='Drafts'){startCompose(m);return}opened=id;m.unread=false;persist();render()}
function bind(){root.querySelectorAll('[data-action]').forEach(el=>el.addEventListener('click',e=>{e.stopPropagation();action(el.dataset.action,el)}));root.querySelectorAll('[data-nav]').forEach(el=>el.onclick=()=>{folder=el.dataset.nav;category='All';query='';opened=null;selected.clear();mobile=false;render()});root.querySelectorAll('[data-category]').forEach(el=>el.onclick=()=>{category=el.dataset.category;selected.clear();render()});root.querySelectorAll('[data-open]').forEach(el=>{el.onclick=()=>openMessage(el.dataset.open);el.onkeydown=e=>{if(e.key==='Enter')openMessage(el.dataset.open)}});root.querySelectorAll('[data-star]').forEach(el=>el.onclick=e=>{e.stopPropagation();const m=mail.find(m=>m.id===el.dataset.star);m.star="'!m.star;persist();render()});root.querySelectorAll('"'[data-select]').forEach(el=>el.onclick=e=>{e.stopPropagation();selected.has(el.dataset.select)?selected.delete(el.dataset.select):selected.add(el.dataset.select);render()});const all=root.querySelector('#select-all');if(all)all.onchange=()=>{selected=all.checked?new Set(filtered().map(m=>m.id)):new Set();render()};const search=root.querySelector('#search');search.oninput=()=>{const pos=search.selectionStart;query=search.value;opened=null;selected.clear();render();const s=root.querySelector('#search');s.focus();s.setSelectionRange(pos,pos)};for(const key of ['to','cc','subject','body']){const el=root.querySelector('#'+key);if(el)el.oninput=()=>{compose[key]=el.value;saveDraft()}}const cf=root.querySelector('#compose-form');if(cf)cf.onsubmit=e=>{e.preventDefault();const sent={...compose,subject:compose.subject||'(No subject)',sender:'Me',initials:'JD',email:'jamie@studio.co',snippet:compose.body.replace(/\\n/g,' '),folder:'Sent',time:'Just now',unread:false,star:false,labels:[],category:'Primary',thread:1,color:'#e0e7da'};mail=mail.filter(m=>m.id"'!==sent.id);mail.unshift(sent);compose=null;persist();render();undo=null;notify('"'Message sent. Find it in Sent.')};const fi=root.querySelector('#file-input');if(fi)fi.onchange=()=>{compose.attachments.push(...Array.from(fi.files).map(f=>f.name));saveDraft();render()};root.querySelectorAll('[data-apply-label]').forEach(el=>el.onclick=()=>{const l=el.dataset.applyLabel,ids=opened?[opened]:[...selected];const remove=ids.every(id=>mail.find(m=>m.id===id).labels.includes(l));pop=null;mutate(ids,m=>({labels:remove?m.labels.filter(x=>x"'!==l):[...new Set([...m.labels,l])]}),remove?'"'Label removed':"'`Labeled ${l}`)});const lf=root.querySelector('"'#label-form');if(lf)lf.onsubmit=e=>{e.preventDefault();const name=root.querySelector('#label-name').value.trim();if("'!name)return;if(labels.some(l=>l.name.toLowerCase()===name.toLowerCase())||['"'Inbox','Starred','Snoozed','Sent','Drafts','Trash','All mail'].includes(name)){notify('That label already exists');return}labels.push({name,color:'#94a88b'});persist();pop=null;render();notify('Label created')};root.querySelectorAll('[id"'^="setting-"]'"').forEach(el=>el.onchange=()=>{settings[el.id.replace('setting-','')]=el.checked;persist();render()});const ff=root.querySelector('#filter-form');if(ff)ff.onsubmit=e=>{e.preventDefault();const f=new FormData(ff);query=[f.get('from')?'from:'+f.get('from'):'',f.get('words'),f.get('unread')?'is:unread':'',f.get('attachment')?'has:attachment':''].filter(Boolean).join(' ');pop=null;opened=null;render()};root.querySelectorAll('[data-snooze]').forEach(el=>el.onclick=()=>{const id=opened;opened=null;pop=null;mutate([id],{snoozed:el.dataset.snooze},'Snoozed until '+el.dataset.snooze)});root.querySelectorAll('[data-contact]').forEach(el=>el.onclick=()=>startCompose({to:el.dataset.contact}));const note=root.querySelector('#quick-note');if(note)note.oninput=()=>localStorage.setItem('gpt6-note',note.value);const tf=root.querySelector('#task-form');if(tf)tf.onsubmit=e=>{e.preventDefault();const tasks=readTasks();tasks.push({text:root.querySelector('#task-name').value,done:false});localStorage.setItem('gpt6-tasks',JSON.stringify(tasks));render()};root.querySelectorAll('[data-task]').forEach(el=>el.onchange=()=>{const tasks=readTasks();tasks[el.dataset.task].done=el.checked;localStorage.setItem('gpt6-tasks',JSON.stringify(tasks));render()});root.querySelectorAll('[data-download]').forEach(el=>el.onclick=()=>{const blob=new Blob(["'`Local attachment preview'"\\n\\n"'${el.dataset.download}'"\\n\\nThis is a demonstration attachment from your GPT-6 mailbox."'`],{type:'"'text/plain'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=el.dataset.download+'.preview.txt';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);notify('Attachment preview downloaded')})}
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if(pop)pop=null;else if(compose){saveDraft();compose=null}else opened=null;render();return}if(['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)||e.metaKey||e.ctrlKey||e.altKey)return;if(e.key==='c'){e.preventDefault();startCompose()}if(e.key==='/'){e.preventDefault();document.querySelector('#search').focus()}if(e.key==='?'){pop={type:'help'};render()}if(e.key==='e'&&opened)action('archive');if(e.key==='#'&&opened)action('trash')});
render();
