import test from 'node:test';
import assert from 'node:assert/strict';
import {seedMail,matches,folderMatch} from './mail.js';
test('mailbox has unique, complete records and every required folder',()=>{const mail=seedMail();assert.equal(new Set(mail.map(m=>m.id)).size,mail.length);for(const folder of ['Inbox','Starred','Sent','Drafts','Trash'])assert.ok(mail.some(m=>folderMatch(m,folder)),folder);for(const m of mail){assert.ok(m.body.length>20);assert.ok(Array.isArray(m.labels));assert.ok(Array.isArray(m.attachments))}});
test('search combines words, sender, label, read state and attachments',()=>{const m=seedMail()[0];assert.ok(matches(m,'brand from:sophie label:work is:unread has:attachment'));assert.equal(matches(m,'brand from:alex'),false);assert.equal(matches({...m,unread:false},'is:unread'),false);assert.equal(matches({...m,attachments:[]},'has:attachment'),false);assert.ok(matches(m,'IS:STARRED'));assert.ok(matches(m,'warmer palette'))});
test('archived and trashed messages obey folder and star rules',()=>{const m=seedMail()[0];assert.equal(folderMatch({...m,folder:'Archive'},'Inbox'),false);assert.ok(folderMatch({...m,folder:'Archive'},'All mail'));assert.ok(folderMatch({...m,folder:'Archive'},'Starred'));assert.equal(folderMatch({...m,folder:'Trash'},'Starred'),false);assert.equal(folderMatch({...m,folder:'Trash'},'All mail'),false);assert.equal(folderMatch({...m,folder:'Trash'},'Work'),false)});
test('snoozed messages leave inbox and remain recoverable',()=>{const m={...seedMail()[0],snoozed:'Tomorrow'};assert.equal(folderMatch(m,'Inbox'),false);assert.ok(folderMatch(m,'Snoozed'));assert.ok(folderMatch({...m,snoozed:null},'Inbox'))});
EOF
